/// The web's `crypto.randomUUID`, replayed: `prefix1`, `prefix2`…
private func counter(_ prefix: String) -> () -> String {
    var n = 0
    return {
        n += 1
        return "\(prefix)\(n)"
    }
}

private func parsed(_ text: String) -> JSONValue {
    guard let value = JSONValue.parse(text) else {
        XCTFail("a golden fixture is not JSON")
        return .null
    }
    return value
}

/// Every path at which two documents differ, so a failure names the field.
private func differences(_ a: JSONValue?, _ b: JSONValue?, _ path: String = "") -> [String] {
    if a == b { return [] }
    if let x = a?.objectValue, let y = b?.objectValue {
        return Set(x.keys).union(y.keys).sorted().flatMap { differences(x[$0], y[$0], "\(path).\($0)") }
    }
    if let x = a?.arrayValue, let y = b?.arrayValue, x.count == y.count {
        return x.indices.flatMap { differences(x[$0], y[$0], "\(path)[\($0)]") }
    }
    return ["\(path): here \(a?.serialized() ?? "absent"), web \(b?.serialized() ?? "absent")"]
}

private func assertSameJSON(_ here: JSONValue?, _ web: JSONValue?, _ name: String,
                            file: StaticString = #filePath, line: UInt = #line) {
    let found = differences(here, web)
    XCTAssertTrue(found.isEmpty, "\(name):\n" + found.joined(separator: "\n"), file: file, line: line)
}

final class TripGoldenMigrationTests: XCTestCase {
    func testEveryGoldenMigratesExactlyAsOnTheWeb() {
        for golden in goldenMigrations {
            let input = parsed(golden.input).objectValue ?? [:]
            let migrated = migrateTripJSON(input, makeId: counter("m"))
            assertSameJSON(.object(migrated), parsed(golden.output), golden.name)
        }
    }

    func testMigratingTheWebsOutputAgainChangesNothing() {
        for golden in goldenMigrations {
            let output = parsed(golden.output).objectValue ?? [:]
            assertSameJSON(.object(migrateTripJSON(output, makeId: counter("x"))), .object(output), golden.name)
        }
    }

    func testEveryGoldenReadsBackAsItselfOnceTyped() {
        // read → write → read is the identity, whatever version it came from.
        for golden in goldenMigrations {
            guard let read = readTripDoc(parsed(golden.input), now: 5, makeId: counter("m")) else {
                XCTFail("\(golden.name) did not read")
                continue
            }
            XCTAssertEqual(readTripDoc(read.json, now: 6, makeId: counter("x")), read, golden.name)
            XCTAssertEqual(read.version, tripDocVersion, golden.name)
        }
    }
}

final class TripGoldenWebWrittenTests: XCTestCase {
    func testATripWrittenByTheWebReadsAndWritesBackUnchanged() throws {
        let web = parsed(webWrittenTrip)
        let read = try XCTUnwrap(readTripDoc(web, makeId: counter("never")))
        assertSameJSON(read.json, web, "web-written trip")
        // …and so does the text: parsed back from what this port writes.
        let text = read.json.serialized()
        XCTAssertEqual(readTripDoc(JSONValue.parse(text), makeId: counter("never")), read)
        XCTAssertEqual(read.json.serialized(), web.serialized())
    }

    func testTheWebWrittenTripIsReadIntoItsRecords() throws {
        let read = try XCTUnwrap(readTripDoc(parsed(webWrittenTrip), makeId: counter("never")))
        XCTAssertEqual(read.sourceId, "winnow.example")
        XCTAssertEqual(read.stages.map(\.places.count), [3, 0])
        XCTAssertEqual(read.stages[1].origin?.chapterId, "ch-12")
        XCTAssertNil(read.stages[0].places[2].coords)
        XCTAssertEqual(read.posts.map(\.kind), [.reel, .carousel, .photo])
        let reel = read.posts[0]
        XCTAssertEqual(reel.badge.camera?.place, .cell(.topLeft))
        XCTAssertEqual(reel.badge.shades.map(\.direction), [.middleVertical, .radial, .bottom])
        XCTAssertEqual(reel.badge.shades[0].falloff, .inOut)
        XCTAssertEqual(reel.badge.shades[2].enabled, false)
        XCTAssertEqual(reel.badge.textOverrides[.caption], "")
        XCTAssertEqual(reel.badge.pieceStyles[.caption]?.color, .some(nil))
        XCTAssertEqual(reel.badge.hook.first?.id, "map")
        XCTAssertEqual(reel.badge.hook.first?.options["futureKey"], "kept")
        XCTAssertEqual(reel.badge.develop?.base, .gain)
        XCTAssertEqual(read.posts[1].slides[0].collage?.cells.count, 3)
        XCTAssertEqual(read.posts[1].slides[0].collage?.enter?.step.inside, true)
        XCTAssertEqual(read.badgeWords.camera?.tags[.iso], "")
        XCTAssertEqual(read.cameraNames?["DJI FC8482"], "DJI Mini 4 Pro")
        XCTAssertNotNil(read.grade.film)
        XCTAssertEqual(Set(read.hookDefaults.keys), [.reel, .photo])
    }
}

